create table if not exists public.market_compras (market_id uuid primary key default gen_random_uuid(), market_mercado_id uuid not null references public.market_mercados(market_id) on delete cascade, market_produto_id uuid not null references public.market_produtos(market_id), market_quantidade integer not null check (market_quantidade > 0), market_preco_custo_unitario numeric(12,2) not null check (market_preco_custo_unitario >= 0), market_data_compra date not null default current_date, market_fornecedor text, market_criado_por uuid references auth.users(id), market_criado_em timestamptz not null default now());
alter table public.market_compras enable row level security;
create policy market_compras_select on public.market_compras for select using (public.market_e_membro(market_mercado_id));
create policy market_compras_insert on public.market_compras for insert with check (public.market_e_membro(market_mercado_id));
create or replace function public.market_registrar_compra(p_market_produto_id uuid, p_market_quantidade integer, p_market_preco_custo_unitario numeric, p_market_data_compra date default current_date, p_market_fornecedor text default null) returns public.market_compras language plpgsql security definer set search_path = public as $$ declare market_produto public.market_produtos; market_compra public.market_compras; begin if p_market_quantidade <= 0 or p_market_preco_custo_unitario < 0 then raise exception 'market_dados_compra_invalidos'; end if; select * into market_produto from public.market_produtos where market_id = p_market_produto_id for update; if market_produto.market_id is null or not public.market_e_membro(market_produto.market_mercado_id) then raise exception 'market_produto_nao_autorizado'; end if; update public.market_produtos set market_quantidade_estoque = market_quantidade_estoque + p_market_quantidade, market_preco_custo = p_market_preco_custo_unitario where market_id = p_market_produto_id; insert into public.market_compras (market_mercado_id, market_produto_id, market_quantidade, market_preco_custo_unitario, market_data_compra, market_fornecedor, market_criado_por) values (market_produto.market_mercado_id, p_market_produto_id, p_market_quantidade, p_market_preco_custo_unitario, p_market_data_compra, p_market_fornecedor, auth.uid()) returning * into market_compra; return market_compra; end $$;
revoke all on function public.market_registrar_compra(uuid, integer, numeric, date, text) from public;
grant execute on function public.market_registrar_compra(uuid, integer, numeric, date, text) to authenticated;
